/**
 * Neo ME (modernization engine) client tool.
 *
 * The agent drives the modernization studio (`/modernize`) through this one
 * tool, the same way the setup assistant drives `/environment/setup` through
 * `onboarding_control`. Everything renders in the workbench beside the chat;
 * nothing navigates.
 */

export const MODERNIZATION_CONTROL_TOOL_NAME = "modernization_control";

/** Action discriminator generated by the SDK for a client-defined tool. */
export const MODERNIZATION_CONTROL_ACTION_KIND =
  `ClientAction_${MODERNIZATION_CONTROL_TOOL_NAME}` as const;

/**
 * Prefix on every receipt posted back into the conversation after a command
 * ran in the browser (and on user answers to choice cards). Hidden from the
 * transcript by `isModernizationReceiptEvent`.
 */
export const MODERNIZATION_RESULT_PREFIX = "[neome result] ";

/**
 * Commands the agent may issue.
 *
 * The complete set ships at once: the agent-server caches a client tool's
 * schema per tool NAME for its whole life and refuses a different schema under
 * the same name (see `src/constants/onboarding-control.ts`). Volatile detail
 * (what has been discovered, which questions are answered, where the plan
 * stands) is answered by `describe`, never encoded in the schema.
 */
export const MODERNIZATION_CONTROL_COMMANDS = [
  // Orientation: the current project state, answers so far, plan, progress,
  // last checkpoint. Call it first, and again after any resume.
  "describe",
  // Discovery: components of the legacy application (frontend, backend,
  // database, jobs, infra, tests...) with language/framework/version and the
  // evidence they rest on (file paths, REA evidence ids, KT pages).
  "record_discovery",
  // Interview: a question rendered as selectable cards with logos. The user's
  // choice comes back as a receipt; the agent must wait for it.
  "ask_choice",
  // The migration plan: phases → steps. Required before `update_progress`.
  "set_plan",
  // A yes/no gate shown as a card (e.g. "Start migrating the backend?").
  "request_approval",
  // Live process: step status, stats, a short note. Drives the big live box.
  "update_progress",
  // A line in the live log (what is being done right now).
  "log",
  // Neo Synth: generate a realistic dataset from the legacy schema and write
  // it (SQL + JSON) into parity/synth/ so both apps run on the same rows.
  "synth_data",
  // Durable resume point: label + arbitrary state the agent will need back.
  "checkpoint",
  // Final report; refused while plan steps are still pending.
  "complete",
] as const;

export type ModernizationControlCommand =
  (typeof MODERNIZATION_CONTROL_COMMANDS)[number];

/** Component kinds in the discovered stack map. Unknown kinds fall back to "other". */
export const COMPONENT_KINDS = [
  "frontend",
  "backend",
  "api",
  "database",
  "mobile",
  "desktop",
  "jobs",
  "messaging",
  "infra",
  "tests",
  "build",
  "auth",
  "other",
] as const;
export type ComponentKind = (typeof COMPONENT_KINDS)[number];

/** Plan phases, in SDLC order. The agent may add steps under each. */
export const MIGRATION_PHASES = [
  "understand",
  "interview",
  "specify",
  "characterize",
  "scaffold",
  "migrate",
  "data",
  "verify",
  "report",
] as const;
export type MigrationPhase = (typeof MIGRATION_PHASES)[number];

export const STEP_STATUSES = [
  "pending",
  "active",
  "done",
  "skipped",
  "failed",
] as const;
export type StepStatus = (typeof STEP_STATUSES)[number];

export const PROJECT_STATUSES = [
  "intake",
  "discovering",
  "interviewing",
  "planned",
  "migrating",
  "paused",
  "verifying",
  "done",
  "failed",
] as const;
export type ProjectStatus = (typeof PROJECT_STATUSES)[number];
